def bind(root,catalog,sources,validate):
    target=root/'tasks'/FILENAME
    if not target.exists():return None,[]
    if target.is_symlink():return None,['Native verification task cannot be a symlink']
    d=dispatch()
    own,errors=validate(root,catalog,sources,filename=FILENAME,label='native output verification',branch=B,base=BASE,paths=P,task_sha=TASK_SHA,gates=GATES,source_bindings=d['SOURCES'],sources_sha=d['SOURCES_SHA'],count_label='nine')
